package main

import (
	"flag"
	"fmt"
	"net"
	"os"
	"strings"

	"github.com/mark3labs/mcp-go/server"
	"github.com/mvanhorn/printing-press-library/library/productivity/ihatepdf-cv/internal/cli"
	mcptools "github.com/mvanhorn/printing-press-library/library/productivity/ihatepdf-cv/internal/mcp"
)

// Transport selection order: --transport flag, then PP_MCP_TRANSPORT env,
// then the first transport declared in the spec (see MCPConfig.Transport).
// HTTP transport is intentionally restricted to loopback addresses because
// this server exposes local files and command execution without a network
// authentication layer.

const (
	defaultHTTPAddr = "127.0.0.1:7777"
)

// version is the printed MCP server's version, overridable at build time via ldflags.
var version = "2026.8.1"

func validateHTTPAddr(addr string) error {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return fmt.Errorf("invalid HTTP bind address %q: %w", addr, err)
	}
	if strings.EqualFold(host, "localhost") {
		return nil
	}
	ip := net.ParseIP(host)
	if ip == nil || !ip.IsLoopback() {
		return fmt.Errorf("HTTP MCP transport only supports loopback bind addresses; refusing %q", addr)
	}
	return nil
}

func main() {
	if err := cli.BindMCPServerProfile(); err != nil {
		fmt.Fprintf(os.Stderr, "MCP client-profile bind failed: %v\n", err)
		os.Exit(1)
	}
	s := server.NewMCPServer(
		"Ihatepdf Cv Local",
		version,
		server.WithToolCapabilities(false),
	)

	// The default MCP catalog is intentionally thin: one composed, read-only
	// artifact identity tool keeps agent context small. Set the surface to
	// full when an operator needs every Cobra command exposed as a tool.
	surface := strings.ToLower(os.Getenv("IHATEPDF_CV_MCP_SURFACE"))
	if surface == "" {
		surface = "thin"
	}
	if surface == "thin" {
		mcptools.RegisterCodeOrchestrationTools(s)
	} else {
		mcptools.RegisterTools(s)
	}

	transport := flag.String("transport", defaultTransport(), "MCP transport: stdio | http")
	addr := flag.String("addr", defaultHTTPAddr, "bind address for http transport (host:port or :port)")
	flag.Parse()

	switch strings.ToLower(*transport) {
	case "stdio":
		if err := server.ServeStdio(s); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	case "http":
		if err := validateHTTPAddr(*addr); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(2)
		}
		httpSrv := server.NewStreamableHTTPServer(s)
		fmt.Fprintf(os.Stderr, "ihatepdf-cv-pp-mcp serving MCP over streamable HTTP at %s\n", *addr)
		if err := httpSrv.Start(*addr); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown --transport %q (supported: stdio, http)\n", *transport)
		os.Exit(2)
	}
}

// defaultTransport reads PP_MCP_TRANSPORT env when set, otherwise falls back
// to "stdio" so running the binary with no args keeps today's behavior.
// Local HTTP clients can pin the transport via env without a flag;
// matches how hosted-agent process supervisors typically pass configuration.
func defaultTransport() string {
	if t := os.Getenv("PP_MCP_TRANSPORT"); t != "" {
		return t
	}
	return "stdio"
}
